'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),os=require('node:os'),path=require('node:path');
const {MessageChannel,Worker}=require('node:worker_threads'),{once}=require('node:events');
assert.equal(process.version,'v26.13.0');const dir=fs.mkdtempSync(path.join(os.tmpdir(),'file-transfer-reference-')),file=path.join(dir,'f');fs.writeFileSync(file,'abc');
const rows=[];function check(name,body){return Promise.resolve().then(body).then(result=>rows.push({name,pass:true,result}),error=>{rows.push({name,pass:false,error:error.stack});throw error;});}
function bounded(promise){let timer;return Promise.race([promise,new Promise((_,reject)=>timer=setTimeout(()=>reject(Error('bounded native reference timed out')),5000))]).finally(()=>clearTimeout(timer));}
(async()=>{try{
 await check('MessagePort same descriptor/OFD and native source observation',async()=>{const h=await fs.promises.open(file,'r');const fd=h.fd,inner=h[Object.getOwnPropertySymbols(h).find(s=>s.description==='kHandle')];const {port1,port2}=new MessageChannel();try{const b=Buffer.alloc(1);fs.readSync(fd,b,0,1,null);const receive=once(port2,'message');port1.postMessage(h,[h]);assert.equal(h.fd,-1);assert.equal(inner.fd,-os.constants.errno.EINVAL);const[received]=await bounded(receive);assert.equal(received.fd,fd);await received.read(b,0,1,null);assert.equal(b.toString(),'b');await received.close();assert.throws(()=>fs.fstatSync(fd),{code:'EBADF'});return{sameFd:true,nativeSourceFd:inner.fd,publicSourceFd:h.fd};}finally{port1.close();port2.close();await h.close();}});
 await check('Worker native receiver owns same fd and close',async()=>{const h=await fs.promises.open(file,'r'),fd=h.fd;const w=new Worker(`const {parentPort}=require('node:worker_threads');parentPort.once('message',async h=>{const fd=h.fd;await h.close();parentPort.postMessage(fd);parentPort.close();});`,{eval:true});try{const reply=once(w,'message'),exit=once(w,'exit');w.postMessage(h,[h]);assert.equal(h.fd,-1);assert.deepEqual(await bounded(reply),[fd]);assert.deepEqual(await bounded(exit),[0]);assert.throws(()=>fs.fstatSync(fd),{code:'EBADF'});return{sameFd:true};}finally{await w.terminate();await h.close();}});
 await check('Duplicate transfer rejected before detaching buffers',async()=>{const h=await fs.promises.open(file,'r'),ab=new ArrayBuffer(8),{port1,port2}=new MessageChannel();try{const fd=h.fd;assert.throws(()=>port1.postMessage({h,ab},[h,h,ab]),{name:'DataCloneError'});assert.equal(ab.byteLength,8);assert.equal(h.fd,fd);return{bufferBytes:8};}finally{port1.close();port2.close();await h.close();}});
 await check('Missing transfer list preserves owner',async()=>{const h=await fs.promises.open(file,'r'),{port1,port2}=new MessageChannel();try{const fd=h.fd;assert.throws(()=>port1.postMessage(h),{name:'DataCloneError'});assert.equal(h.fd,fd);return{retained:true};}finally{port1.close();port2.close();await h.close();}});
 await check('Active public operation rejects transfer after AB-first detach',async()=>{const h=await fs.promises.open(file,'r'),ab=new ArrayBuffer(8),{port1,port2}=new MessageChannel();try{const pending=h.read(Buffer.alloc(1),0,1,null);assert.throws(()=>port1.postMessage({h,ab},[h,ab]),{name:'DataCloneError'});assert.equal(ab.byteLength,0);await pending;assert(h.fd>=0);return{bufferBytes:0,ownerRetained:true};}finally{port1.close();port2.close();await h.close();}});
 await check('Closing public handle rejects transfer with actual phase order',async()=>{const h=await fs.promises.open(file,'r'),ab=new ArrayBuffer(8),{port1,port2}=new MessageChannel();try{const pending=h.close();assert.throws(()=>port1.postMessage({h,ab},[h,ab]),{name:'DataCloneError'});assert.equal(ab.byteLength,0);await pending;return{bufferBytes:0,closed:true};}finally{port1.close();port2.close();await h.close();}});
 await check('Closed destination still moves then retires fd synchronously',async()=>{const h=await fs.promises.open(file,'r'),fd=h.fd,{port1,port2}=new MessageChannel();try{port1.close();port1.postMessage(h,[h]);assert.equal(h.fd,-1);assert.throws(()=>fs.fstatSync(fd),{code:'EBADF'});return{moved:true,retired:true};}finally{port2.close();await h.close();}});
 await check('Worker exit retires decoded but unread FileHandle',async()=>{const h=await fs.promises.open(file,'r'),fd=h.fd;const w=new Worker(`process.exit(0)`,{eval:true,workerData:h,transferList:[h]});assert.equal(h.fd,-1);assert.deepEqual(await bounded(once(w,'exit')),[0]);assert.throws(()=>fs.fstatSync(fd),{code:'EBADF'});await h.close();return{retired:true};});
}finally{fs.rmSync(dir,{recursive:true,force:true});console.log(JSON.stringify({rows,pass:rows.filter(x=>x.pass).length,fail:rows.filter(x=>!x.pass).length,scope:'Exact pinned native Node26 public transfer reference only; not candidate SC/receiver/JSAPI execution'}));}})().catch(error=>{console.error(error);process.exitCode=1;});
